CREATE OR REPLACE FUNCTION public.fn_get_material_product_by_sku(p_sku character varying)  RETURNS TABLE(id uuid, sku character varying, name character varying, description text, category character varying, image_url character varying, material_type character varying, safety_instructions text, age_min_months integer, age_max_months integer, usage_restrictions text, cleaning_instructions text, return_policy text, is_active boolean, created_at timestamp with time zone, updated_at timestamp with time zone, off_id uuid, off_prod_id uuid, allow_purchase boolean, purchase_price numeric, allow_borrow boolean, rental_fee numeric, refundable_deposit numeric, default_loan_duration_days integer, max_loan_duration_days integer, currency character varying, off_is_active boolean, bal_id uuid, total_stock integer, available_stock integer, reserved_stock integer, dispatched_stock integer, on_loan_stock integer, under_inspection_stock integer, under_cleaning_stock integer, damaged_stock integer, missing_stock integer, retired_stock integer)  LANGUAGE sql  STABLE AS $function$     SELECT          p.id, p.sku, p.name, p.description, p.category, p.image_url,         p.material_type, p.safety_instructions, p.age_min_months, p.age_max_months,         p.usage_restrictions, p.cleaning_instructions, p.return_policy,         p.is_active, p.created_at, p.updated_at,         o.id AS off_id, o.material_product_id AS off_prod_id, o.allow_purchase, o.purchase_price,         o.allow_borrow, o.rental_fee, o.refundable_deposit, o.default_loan_duration_days,         o.max_loan_duration_days, o.currency, o.is_active AS off_is_active,         b.id AS bal_id, b.total_stock, b.available_stock, b.reserved_stock, b.dispatched_stock,         b.on_loan_stock, b.under_inspection_stock, b.under_cleaning_stock, b.damaged_stock,         b.missing_stock, b.retired_stock     FROM material_products p     LEFT JOIN material_offerings o ON p.id = o.material_product_id     LEFT JOIN inventory_balances b ON p.id = b.material_product_id     WHERE p.sku = p_sku; $function$ ;
